      assert(stateOf(kit, ref).reservedAmount("tx-a1-1").minorUnits == "100")
      val r2 = reserve_sourceCommit(kit, ref, "tx-a1-1", "a1")
      assert(r2.error.isEmpty)
      val s = stateOf(kit, ref)
