  import net.imadz.infra.saga.strict.{ConfirmedReceipt, NotExecuted, OperationIdentity, OperationRequest, PhaseBinding, PhaseOutcome, PhasePort, StrictSagaDefinition, TransactionIdentity, Unknown}
  import scala.concurrent.Future
  private def p19Events(kit: ActorTestKit, entityId: String, txid: String): Vector[Any] =
    PersistenceTestKit(kit.system).persistedInStorage(PersistenceId(net.imadz.metarch.application.aggregates.CreditBalanceAggregate.entityTypeKey.name, entityId).id)
      .filter {
        case e: net.imadz.metarch.domain.entities.CreditBalanceEntity.ReserveFundsConfirmed => e.txid == txid
        case e: net.imadz.metarch.domain.entities.CreditBalanceEntity.RecordIncomingCreditsConfirmed => e.txid == txid
        case e: net.imadz.metarch.domain.entities.CreditBalanceEntity.DeductFundsConfirmed => e.txid == txid
        case e: net.imadz.metarch.domain.entities.CreditBalanceEntity.CommitIncomingCreditsConfirmed => e.txid == txid
        case e: net.imadz.metarch.domain.entities.CreditBalanceEntity.ReleaseReservedFundsConfirmed => e.txid == txid
        case e: net.imadz.metarch.domain.entities.CreditBalanceEntity.CancelIncomingCreditConfirmed => e.txid == txid
        case _ => false
      }.toVector

  private def p19Identity(host: SagaModule.Host, txid: String, resource: String, source: Boolean): OperationIdentity = {
    val digest = "sha256:" + "0" * 64
    OperationIdentity(TransactionIdentity(txid, SagaModule.Name, SagaModule.Version, digest,
      SagaModule.DefinitionDigest, host.argsCodec.pin, digest),
      if (source) "source" else "target", resource, if (source) "reserve-source" else "reserve-target", Phase.Prepare)
  }

  private def p19Refusal(host: SagaModule.Host, attempts: java.util.concurrent.atomic.AtomicInteger)
      (implicit ec: ExecutionContext): StrictSagaDefinition[SagaModule.Args] = {
    val original = SagaModule.definition(host)
    original.copy(participants = (args: SagaModule.Args) => original.participants(args).map { participant =>
      if (participant.participantId != "target") participant else {
        val binding = host.reserve_targetPrepareBinding
        val port = new PhasePort[SagaModule.Args, SagaModule.Reserve_targetPrepareReceipt] {
          override def receiptCodec = binding.receiptCodec
          override def querySafety = binding.querySafety
          override def execute(request: OperationRequest[SagaModule.Args]) = {
            attempts.incrementAndGet()
            // Explicit test-only admission refusal: no target command is dispatched.
            Future.successful(NotExecuted(request.identity, "P19_TEST_PRE_DISPATCH_REFUSAL", safeToRetry = true))
          }
          override def query(request: OperationRequest[SagaModule.Args]) =
            binding.query(request.identity, SagaModule.Reserve_targetPrepareInput(request.identity.transaction.transactionId, request.args.to, request.args.amount))
        }
        participant.copy(phases = participant.phases.updated(Phase.Prepare, PhaseBinding(port)))
      }
    })
  }

