          if (source) host.reserve_sourcePrepareBinding.execute(identity, SagaModule.Reserve_sourcePrepareInput(txid, id, value))
          else host.reserve_targetPrepareBinding.execute(identity, SagaModule.Reserve_targetPrepareInput(txid, id, value)), 10.seconds)
        def query(value: net.imadz.metarch.domain.values.Money): PhaseOutcome[Any] = Await.result(
          if (source) host.reserve_sourcePrepareBinding.query(identity, SagaModule.Reserve_sourcePrepareInput(txid, id, value))
          else host.reserve_targetPrepareBinding.query(identity, SagaModule.Reserve_targetPrepareInput(txid, id, value)), 10.seconds)
        val amount = Money("30", Currency)
        val first = execute(amount)
        assert(first.isInstanceOf[ConfirmedReceipt[_]])
        val stored = stateOf(kit, entityRef(sharding, id))
        val events = p19Events(kit, id, txid)
        assert(events.size == 1)
        assert(execute(amount) == first)
        assert(query(amount) == first)
        first match {
          case ConfirmedReceipt(_, receipt: SagaModule.Reserve_sourcePrepareReceipt) =>
            assert(host.reserve_sourcePrepareBinding.receiptCodec.encode(receipt) ==
              host.reserve_sourcePrepareBinding.receiptCodec.encode(SagaModule.Reserve_sourcePrepareReceipt(txid, stored.reservedAmount(txid))))
          case ConfirmedReceipt(_, receipt: SagaModule.Reserve_targetPrepareReceipt) =>
            assert(host.reserve_targetPrepareBinding.receiptCodec.encode(receipt) ==
              host.reserve_targetPrepareBinding.receiptCodec.encode(SagaModule.Reserve_targetPrepareReceipt(txid, stored.incomingCredits(txid))))
          case _ => fail("missing typed durable receipt")
        }
        for (conflict <- Vector(Money("31", Currency), Money("30", "USD"), Money("030", Currency))) {
          assert(query(conflict) match { case Unknown(_, reason) => reason.startsWith("MONEY_PREPARE_PAYLOAD_CONFLICT"); case _ => false })
          assert(execute(conflict) match { case Unknown(_, reason) => reason.startsWith("MONEY_PREPARE_PAYLOAD_CONFLICT"); case _ => false })
        }
        assert(p19Events(kit, id, txid) == events)
        assert(stateOf(kit, entityRef(sharding, id)) == stored)
      }
    } finally kit.shutdownTestKit()
  }

