  for (conflict <- Vector(false, true)) test("P19 ACK loss: real durable Prepare is queried after actor recovery; conflict=" + conflict) {
    val port = freePort()
    val name = "MoneyAckP19" + conflict
    val kit = ActorTestKit(name, clusterConfig(port, "\"akka://" + name + "@127.0.0.1:" + port + "\""))
    val held = scala.concurrent.Promise[PhaseOutcome[SagaModule.Reserve_sourcePrepareReceipt]]()
    try {
      val sharding = initSharding(kit)
      awaitMembers(kit, 1)
      seedFunds(kit, From, "seed-ack-from")
      seedFunds(kit, To, "seed-ack-to")
      implicit val ec: ExecutionContext = kit.system.executionContext
      val host = new FixtureHost(kit.system, sharding)
      val original = SagaModule.definition(host)
      val durable = scala.concurrent.Promise[SagaModule.Reserve_sourcePrepareReceipt]()
      val queried = scala.concurrent.Promise[PhaseOutcome[SagaModule.Reserve_sourcePrepareReceipt]]()
      val executes = new java.util.concurrent.atomic.AtomicInteger()
      val binding = host.reserve_sourcePrepareBinding
      val wrapped = new PhasePort[SagaModule.Args, SagaModule.Reserve_sourcePrepareReceipt] {
        override def receiptCodec = binding.receiptCodec
        override def querySafety = binding.querySafety
        override def execute(request: OperationRequest[SagaModule.Args]) = {
          executes.incrementAndGet()
          val sent = if (conflict) Money("21", Currency) else request.args.amount
          binding.execute(request.identity, SagaModule.Reserve_sourcePrepareInput(request.identity.transaction.transactionId, request.args.from, sent)).flatMap {
            case ConfirmedReceipt(_, receipt) => durable.trySuccess(receipt); held.future
            case other => Future.successful(other)
          }
        }
        override def query(request: OperationRequest[SagaModule.Args]) =
          binding.query(request.identity, SagaModule.Reserve_sourcePrepareInput(request.identity.transaction.transactionId, request.args.from, request.args.amount))
            .map { outcome => queried.trySuccess(outcome); outcome }
      }
      val definition = original.copy(participants = (args: SagaModule.Args) => original.participants(args).map(p =>
        if (p.participantId == "source") p.copy(phases = p.phases.updated(Phase.Prepare, PhaseBinding(wrapped))) else p))
      val pid = PersistenceId.ofUniqueId("strict-saga/p19-ack")
      def spawn() = kit.spawn(StrictSagaCoordinator(pid, definition, FixtureReconcileAuthorizer(ReconcileToken), host.settings))
      val first = spawn()
      val txid = "p19-ack"
      first ! StrictSagaCoordinator.Start(txid, host.argsCodec.encode(SagaModule.Args(From, To, Money("20", Currency))),
        kit.createTestProbe[StrictSagaCoordinator.Reply]().ref)
      val receipt = Await.result(durable.future, 10.seconds)
      assert(receipt.amount.minorUnits == (if (conflict) "21" else "20"))
      val priorEvents = p19Events(kit, From, txid)
      assert(priorEvents.size == 1)
      assert(stateOf(kit, entityRef(sharding, From)).reservedAmount(txid) == receipt.amount)
      val interrupted = awaitTerminal(kit, first)
      assert(interrupted.status == StrictStatus.RecoveryRequired)
      assert(interrupted.evidence.values.exists(_.isInstanceOf[Evidence.Uncertain]))
      // ActorTestKit.stop waits for deathwatch termination; the same journal remains.
      kit.stop(first)
      val again = spawn()
      val probe = kit.createTestProbe[StrictSagaCoordinator.Reply]()
      again ! StrictSagaCoordinator.GetStatus(probe.ref)
      val recovered = probe.expectMessageType[StrictSagaCoordinator.Status].state
      assert(recovered.identity == interrupted.identity)
      assert(recovered.status == StrictStatus.RecoveryRequired)
      again ! StrictSagaCoordinator.Reconcile(recovered.identity.get, ReconcileToken, 32, probe.ref)
      val evidence = Await.result(queried.future, 10.seconds)
      if (conflict) {
        assert(evidence match { case Unknown(_, reason) => reason.startsWith("MONEY_PREPARE_PAYLOAD_CONFLICT"); case _ => false })
        assert(awaitTerminal(kit, again).status == StrictStatus.RecoveryRequired)
        assert(p19Events(kit, From, txid) == priorEvents)
        assert(p19Events(kit, To, txid).isEmpty)
        assert(balance(kit, entityRef(sharding, From)) == BigInt("99979"))
        assert(balance(kit, entityRef(sharding, To)) == BigInt("100000"))
      } else {
        assert(evidence == ConfirmedReceipt(OperationIdentity(recovered.identity.get, "source", From, "reserve-source", Phase.Prepare), receipt))
        val finished = awaitTerminal(kit, again)
        assert(finished.status == StrictStatus.Succeeded)
        assert(p19Events(kit, From, txid).count(_.isInstanceOf[net.imadz.metarch.domain.entities.CreditBalanceEntity.ReserveFundsConfirmed]) == 1)
        assert(balance(kit, entityRef(sharding, From)) == BigInt("99980"))
        assert(balance(kit, entityRef(sharding, To)) == BigInt("100020"))
        assertPublished(kit, sharding, finished, "succeeded")
      }
      assert(executes.get == 1)
    } finally {
      held.tryFailure(new IllegalStateException("test ACK channel closed"))
      kit.shutdownTestKit()
    }
  }

  private def p20Port(host: SagaModule.Host, source: Boolean, commit: Boolean)(implicit ec: ExecutionContext): PhasePort[SagaModule.Args, String] = {
    val phase = if (commit) Phase.Commit else Phase.Compensate
    val codec = new net.imadz.infra.saga.strict.PayloadCodec[String] {
      override val pin = if (source && commit) host.reserve_sourceCommitBinding.receiptCodec.pin
        else if (source) host.reserve_sourceCompensateBinding.receiptCodec.pin
        else if (commit) host.reserve_targetCommitBinding.receiptCodec.pin else host.reserve_targetCompensateBinding.receiptCodec.pin
      override def encode(value: String) = if (source && commit) host.reserve_sourceCommitBinding.receiptCodec.encode(SagaModule.Reserve_sourceCommitReceipt(value))
        else if (source) host.reserve_sourceCompensateBinding.receiptCodec.encode(SagaModule.Reserve_sourceCompensateReceipt(value))
        else if (commit) host.reserve_targetCommitBinding.receiptCodec.encode(SagaModule.Reserve_targetCommitReceipt(value))
        else host.reserve_targetCompensateBinding.receiptCodec.encode(SagaModule.Reserve_targetCompensateReceipt(value))
      override def decode(bytes: com.google.protobuf.ByteString) = if (source && commit) host.reserve_sourceCommitBinding.receiptCodec.decode(bytes).map(_.txid)
        else if (source) host.reserve_sourceCompensateBinding.receiptCodec.decode(bytes).map(_.txid)
        else if (commit) host.reserve_targetCommitBinding.receiptCodec.decode(bytes).map(_.txid)
        else host.reserve_targetCompensateBinding.receiptCodec.decode(bytes).map(_.txid)
    }
    new PhasePort[SagaModule.Args, String] {
      override def receiptCodec = codec
      override def querySafety = net.imadz.infra.saga.strict.QuerySafety.DeclaredReadOnly
      private def invoke(request: OperationRequest[SagaModule.Args], query: Boolean): Future[PhaseOutcome[String]] = {
        val txid = request.identity.transaction.transactionId
        val id = if (source) request.args.from else request.args.to
        val identity = request.identity.copy(phase = phase)
        if (source && commit) {
          val b = host.reserve_sourceCommitBinding; val in = SagaModule.Reserve_sourceCommitInput(txid, id)
          (if (query) b.query(identity, in) else b.execute(identity, in)).map {
            case ConfirmedReceipt(i, r) => ConfirmedReceipt(i, r.txid); case other: NotExecuted => other; case other: Unknown => other
          }
        } else if (source) {
          val b = host.reserve_sourceCompensateBinding; val in = SagaModule.Reserve_sourceCompensateInput(txid, id)
          (if (query) b.query(identity, in) else b.execute(identity, in)).map {
            case ConfirmedReceipt(i, r) => ConfirmedReceipt(i, r.txid); case other: NotExecuted => other; case other: Unknown => other
          }
        } else if (commit) {
          val b = host.reserve_targetCommitBinding; val in = SagaModule.Reserve_targetCommitInput(txid, id)
          (if (query) b.query(identity, in) else b.execute(identity, in)).map {
            case ConfirmedReceipt(i, r) => ConfirmedReceipt(i, r.txid); case other: NotExecuted => other; case other: Unknown => other
          }
        } else {
          val b = host.reserve_targetCompensateBinding; val in = SagaModule.Reserve_targetCompensateInput(txid, id)
          (if (query) b.query(identity, in) else b.execute(identity, in)).map {
            case ConfirmedReceipt(i, r) => ConfirmedReceipt(i, r.txid); case other: NotExecuted => other; case other: Unknown => other
          }
        }
      }
      override def execute(request: OperationRequest[SagaModule.Args]) = invoke(request, false)
      override def query(request: OperationRequest[SagaModule.Args]) = invoke(request, true)
    }
  }

