  test("P20 synthetic classification: absence, corrupt/conflicting markers, false ACK and query failure are not runtime evidence") {
    val port = freePort(); val name = "MoneySyntheticP20"
    val kit = ActorTestKit(name, clusterConfig(port, "\"akka://" + name + "@127.0.0.1:" + port + "\""))
    try {
      implicit val ec: ExecutionContext = kit.system.executionContext
      val txid = "p20-synthetic"; val amount = Money("30", Currency)
      def synthetic(id: String): net.imadz.metarch.domain.entities.CreditBalanceEntity.CreditBalanceState = {
        val base = net.imadz.metarch.domain.entities.CreditBalanceEntity.empty(id)
        val marker = if (id.contains("null")) Map(txid -> null.asInstanceOf[net.imadz.metarch.domain.values.Money])
          else if (id.contains("bad")) Map(txid -> Money("", Currency)) else Map(txid -> amount)
        if (id.contains("empty") || id.contains("failure")) base
        else if (id.contains("live-only")) base.copy(reservedAmount = Map(txid -> amount), incomingCredits = Map(txid -> amount))
        else if (id.contains("both")) base.copy(committed = marker, compensated = marker)
        else if (id.contains("live") && id.contains("commit")) base.copy(committed = marker,
          reservedAmount = Map(txid -> amount), incomingCredits = Map(txid -> amount))
        else if (id.contains("live") && id.contains("compensate")) base.copy(compensated = marker,
          reservedAmount = Map(txid -> amount), incomingCredits = Map(txid -> amount))
        else if (id.contains("commit")) base.copy(committed = marker) else base.copy(compensated = marker)
      }
      val observed = scala.concurrent.Promise[Unit]()
      val sharding = ClusterSharding(kit.system)
      sharding.init(Entity(net.imadz.metarch.application.aggregates.CreditBalanceAggregate.entityTypeKey) { ctx =>
        akka.actor.typed.scaladsl.Behaviors.receiveMessage[net.imadz.metarch.application.aggregates.CreditBalanceProtocol.CreditBalanceCommandFamily] {
          case CreditBalanceProtocol.GetBalance(replyTo) if ctx.entityId.contains("failure") =>
            observed.trySuccess(()); akka.actor.typed.scaladsl.Behaviors.stopped
          case CreditBalanceProtocol.GetBalance(replyTo) =>
            replyTo ! CreditBalanceProtocol.GetCreditBalanceStateReply(synthetic(ctx.entityId)); akka.actor.typed.scaladsl.Behaviors.same
          case c: CreditBalanceProtocol.DeductFunds => c.replyTo ! CreditBalanceProtocol.CreditBalanceReply(None); akka.actor.typed.scaladsl.Behaviors.same
          case c: CreditBalanceProtocol.ReleaseReservedFunds => c.replyTo ! CreditBalanceProtocol.CreditBalanceReply(None); akka.actor.typed.scaladsl.Behaviors.same
          case c: CreditBalanceProtocol.CommitIncomingCredits => c.replyTo ! CreditBalanceProtocol.CreditBalanceReply(None); akka.actor.typed.scaladsl.Behaviors.same
          case c: CreditBalanceProtocol.CancelIncomingCredit => c.replyTo ! CreditBalanceProtocol.CreditBalanceReply(None); akka.actor.typed.scaladsl.Behaviors.same
          case _ => akka.actor.typed.scaladsl.Behaviors.unhandled
        }
      })
      awaitMembers(kit, 1)
      val host = new FixtureHost(kit.system, sharding)
      for (source <- Vector(true, false); commit <- Vector(true, false)) {
        val terminal = p20Port(host, source, commit)
        def request(id: String) = OperationRequest(p19Identity(host, txid, id, source).copy(phase = if (commit) Phase.Commit else Phase.Compensate), SagaModule.Args(id, id, amount))
        for (suffix <- Vector("empty", "live-only")) {
          val r = request("p20-" + suffix)
          assert(Await.result(terminal.query(r), 10.seconds) match { case NotExecuted(_, _, true) => true; case _ => false })
          assert(Await.result(terminal.execute(r), 10.seconds) match { case Unknown(_, reason) => reason.startsWith("MONEY_TERMINAL_ACK_WITHOUT_FACT"); case _ => false })
        }
        for (suffix <- Vector("both", (if (commit) "commit" else "compensate") + "-live", (if (commit) "commit" else "compensate") + "-null", (if (commit) "commit" else "compensate") + "-bad")) {
          val outcome = Await.result(terminal.query(request("p20-" + suffix)), 10.seconds)
          val expected = if (suffix.contains("null") || suffix.contains("bad")) "MONEY_TERMINAL_FACT_UNAVAILABLE" else "MONEY_TERMINAL_FACT_CONFLICT"
          assert(outcome match { case Unknown(_, reason) => reason.startsWith(expected); case _ => false })
        }
      }
      val failed = p20Port(host, true, true).query(OperationRequest(p19Identity(host, txid, "p20-failure", true).copy(phase = Phase.Commit), SagaModule.Args("p20-failure", "p20-failure", amount)))
      Await.result(observed.future, 10.seconds)
      assert(Await.result(failed, 10.seconds) match { case Unknown(_, reason) => reason.startsWith("phase evidence query failed"); case _ => false })
    } finally kit.shutdownTestKit()
  }

  for ((source, commit, conflict) <- Vector((true, true, false), (false, true, false),
    (true, false, false), (false, false, false), (true, true, true), (true, false, true)))
    test("P20 terminal ACK loss: real durable command and authorized actor recovery; source=" + source + "; commit=" + commit + "; opposite-injection=" + conflict) {
      val port = freePort(); val name = "MoneyAckP20" + source + commit + conflict
      val kit = ActorTestKit(name, clusterConfig(port, "\"akka://" + name + "@127.0.0.1:" + port + "\""))
      val held = scala.concurrent.Promise[PhaseOutcome[String]]()
      val prepareHeld = scala.concurrent.Promise[PhaseOutcome[SagaModule.Reserve_targetPrepareReceipt]]()
      try {
        val sharding = initSharding(kit); awaitMembers(kit, 1)
        seedFunds(kit, From, "seed-p20-from"); seedFunds(kit, To, "seed-p20-to")
        implicit val ec: ExecutionContext = kit.system.executionContext
        val host = new FixtureHost(kit.system, sharding)
        val original = SagaModule.definition(host)
        val phase = if (commit) Phase.Commit else Phase.Compensate
        val actual = p20Port(host, source, commit)
        val injected = p20Port(host, source, !commit)
        val durable = scala.concurrent.Promise[String]()
        val queried = scala.concurrent.Promise[PhaseOutcome[String]]()
        val preparedTarget = scala.concurrent.Promise[SagaModule.Reserve_targetPrepareReceipt]()
        val executes = new java.util.concurrent.atomic.AtomicInteger()
        val refusalAttempts = new java.util.concurrent.atomic.AtomicInteger()
        val wrapped = new PhasePort[SagaModule.Args, String] {
          override def receiptCodec = actual.receiptCodec
          override def querySafety = actual.querySafety
          override def execute(request: OperationRequest[SagaModule.Args]) = {
            executes.incrementAndGet()
            val sent = if (conflict) request.copy(identity = request.identity.copy(phase = if (commit) Phase.Compensate else Phase.Commit)) else request
            (if (conflict) injected.execute(sent) else actual.execute(sent)).flatMap {
              case ConfirmedReceipt(_, receipt) => durable.trySuccess(receipt); held.future
              case other => Future.successful(other)
            }
          }
          override def query(request: OperationRequest[SagaModule.Args]) = actual.query(request).map { outcome => queried.trySuccess(outcome); outcome }
        }
        val targetPrepare = new PhasePort[SagaModule.Args, SagaModule.Reserve_targetPrepareReceipt] {
          private val b = host.reserve_targetPrepareBinding
          override def receiptCodec = b.receiptCodec
          override def querySafety = b.querySafety
          override def execute(request: OperationRequest[SagaModule.Args]) = {
            if (source) {
              refusalAttempts.incrementAndGet()
              Future.successful(NotExecuted(request.identity, "P20_TEST_PRE_DISPATCH_TARGET_REFUSAL", safeToRetry = true))
            } else b.execute(request.identity, SagaModule.Reserve_targetPrepareInput(request.identity.transaction.transactionId, request.args.to, request.args.amount)).flatMap {
              case ConfirmedReceipt(_, receipt) => preparedTarget.trySuccess(receipt); prepareHeld.future
              case other => Future.successful(other)
            }
          }
          override def query(request: OperationRequest[SagaModule.Args]) =
            b.query(request.identity, SagaModule.Reserve_targetPrepareInput(request.identity.transaction.transactionId, request.args.to, request.args.amount))
        }
        val definition = original.copy(participants = (args: SagaModule.Args) => original.participants(args).map { p =>
          val withTerminal = if (p.participantId == (if (source) "source" else "target")) p.copy(phases = p.phases.updated(phase, PhaseBinding(wrapped))) else p
          if (!commit && p.participantId == "target") withTerminal.copy(phases = withTerminal.phases.updated(Phase.Prepare, PhaseBinding(targetPrepare))) else withTerminal
        })
        val pid = PersistenceId.ofUniqueId("strict-saga/p20-ack")
        def spawn() = kit.spawn(StrictSagaCoordinator(pid, definition, FixtureReconcileAuthorizer(ReconcileToken), host.settings))
        val first = spawn(); val txid = "p20-ack"
        first ! StrictSagaCoordinator.Start(txid, host.argsCodec.encode(SagaModule.Args(From, To, Money("20", Currency))), kit.createTestProbe[StrictSagaCoordinator.Reply]().ref)
        if (!commit && !source) {
          Await.result(preparedTarget.future, 10.seconds)
          val probe = kit.createTestProbe[StrictSagaCoordinator.Reply]()
          first ! StrictSagaCoordinator.GetStatus(probe.ref)
          val beforeAbort = probe.expectMessageType[StrictSagaCoordinator.Status].state
          assert(!beforeAbort.commitDecision && beforeAbort.pending.exists(_.identity.phase == Phase.Prepare))
          first ! StrictSagaCoordinator.Abort(beforeAbort.identity.get, "P20_TEST_AUTHORIZED_ABORT_BEFORE_COMMIT", probe.ref)
          assert(probe.expectMessageType[StrictSagaCoordinator.Status].state.abortRequested)
        }
        assert(Await.result(durable.future, 10.seconds) == txid)
        val interrupted = awaitTerminal(kit, first)
        assert(interrupted.status == StrictStatus.RecoveryRequired)
        assert(interrupted.commitDecision == commit && interrupted.abortRequested == !commit)
        val operation = OperationIdentity(interrupted.identity.get, if (source) "source" else "target", if (source) From else To,
          if (source) "reserve-source" else "reserve-target", phase)
        assert(interrupted.evidence(operation).isInstanceOf[Evidence.Uncertain])
        val sourceBefore = stateOf(kit, entityRef(sharding, From)); val targetBefore = stateOf(kit, entityRef(sharding, To))
        val sourceEvents = p19Events(kit, From, txid); val targetEvents = p19Events(kit, To, txid)
        assert((if (commit != conflict) (if (source) sourceBefore else targetBefore).committed else (if (source) sourceBefore else targetBefore).compensated)(txid) == Money("20", Currency))
        if (commit && source) assert(targetBefore.incomingCredits(txid) == Money("20", Currency))
        if (commit && !source) assert(sourceBefore.committed(txid) == Money("20", Currency))
        if (!commit && source) assert(targetEvents.isEmpty && refusalAttempts.get == 1)
        if (!commit && !source) assert(sourceBefore.reservedAmount(txid) == Money("20", Currency))
        kit.stop(first)
        val again = spawn(); val probe = kit.createTestProbe[StrictSagaCoordinator.Reply]()
        again ! StrictSagaCoordinator.GetStatus(probe.ref)
        val recovered = probe.expectMessageType[StrictSagaCoordinator.Status].state
        assert(recovered == interrupted)
        assert(p19Events(kit, From, txid) == sourceEvents && p19Events(kit, To, txid) == targetEvents)
        assert(executes.get == 1)
        again ! StrictSagaCoordinator.Reconcile(recovered.identity.get, ReconcileToken, 32, probe.ref)
        val evidence = Await.result(queried.future, 10.seconds)
        val finished = awaitTerminal(kit, again)
        if (conflict) {
          assert(evidence match { case Unknown(_, reason) => reason.startsWith("MONEY_TERMINAL_FACT_CONFLICT"); case _ => false })
          assert(finished.status == StrictStatus.RecoveryRequired && finished.commitDecision == commit && finished.abortRequested == !commit)
          assert(stateOf(kit, entityRef(sharding, From)) == sourceBefore && stateOf(kit, entityRef(sharding, To)) == targetBefore)
          assert(p19Events(kit, From, txid) == sourceEvents && p19Events(kit, To, txid) == targetEvents)
        } else {
          assert(evidence == ConfirmedReceipt(operation, txid))
          assert(finished.status == (if (commit) StrictStatus.Succeeded else StrictStatus.Aborted))
          assert(balance(kit, entityRef(sharding, From)) == BigInt(if (commit) "99980" else "100000"))
          assert(balance(kit, entityRef(sharding, To)) == BigInt(if (commit) "100020" else "100000"))
          val selectedBefore = if (source) sourceEvents else targetEvents
          val selectedAfter = p19Events(kit, if (source) From else To, txid)
          assert(selectedAfter == selectedBefore)
          val all = p19Events(kit, From, txid) ++ p19Events(kit, To, txid)
          if (commit) {
            assert(all.count(_.isInstanceOf[net.imadz.metarch.domain.entities.CreditBalanceEntity.DeductFundsConfirmed]) == 1)
            assert(all.count(_.isInstanceOf[net.imadz.metarch.domain.entities.CreditBalanceEntity.CommitIncomingCreditsConfirmed]) == 1)
            assert(!all.exists(e => e.isInstanceOf[net.imadz.metarch.domain.entities.CreditBalanceEntity.ReleaseReservedFundsConfirmed] || e.isInstanceOf[net.imadz.metarch.domain.entities.CreditBalanceEntity.CancelIncomingCreditConfirmed]))
          } else {
            assert(all.count(_.isInstanceOf[net.imadz.metarch.domain.entities.CreditBalanceEntity.ReleaseReservedFundsConfirmed]) == 1)
            assert(all.count(_.isInstanceOf[net.imadz.metarch.domain.entities.CreditBalanceEntity.CancelIncomingCreditConfirmed]) == (if (source) 0 else 1))
            assert(!all.exists(e => e.isInstanceOf[net.imadz.metarch.domain.entities.CreditBalanceEntity.DeductFundsConfirmed] || e.isInstanceOf[net.imadz.metarch.domain.entities.CreditBalanceEntity.CommitIncomingCreditsConfirmed]))
          }
          assert(finished.evidence(operation) == Evidence.Confirmed(operation, actual.receiptCodec.encode(txid)))
          assert(executes.get == 1)
          assertPublished(kit, sharding, finished, if (commit) "succeeded" else "compensated")
        }
        assert(executes.get == 1)
      } finally {
        held.tryFailure(new IllegalStateException("P20 test terminal ACK channel closed"))
        prepareHeld.tryFailure(new IllegalStateException("P20 test Prepare ACK channel closed"))
        kit.shutdownTestKit()
      }
    }

  private def p21AllEvents(kit: ActorTestKit, id: String): Vector[Any] =
    PersistenceTestKit(kit.system).persistedInStorage(PersistenceId(net.imadz.metarch.application.aggregates.CreditBalanceAggregate.entityTypeKey.name, id).id).toVector

  private def p21PrepareCommand(source: Boolean, txid: String, id: String, amount: net.imadz.metarch.domain.values.Money, reply: ActorRef[CreditBalanceProtocol.CreditBalanceReply]): net.imadz.metarch.application.aggregates.CreditBalanceProtocol.CreditBalanceCommandFamily =
    if (source) CreditBalanceProtocol.ReserveFunds(txid, id, amount, reply)
    else CreditBalanceProtocol.RecordIncomingCredits(txid, id, amount, reply)

  private def p21TerminalCommand(source: Boolean, commit: Boolean, txid: String, id: String, reply: ActorRef[CreditBalanceProtocol.CreditBalanceReply]): net.imadz.metarch.application.aggregates.CreditBalanceProtocol.CreditBalanceCommandFamily =
    if (source && commit) CreditBalanceProtocol.DeductFunds(txid, id, reply)
    else if (source) CreditBalanceProtocol.ReleaseReservedFunds(txid, id, reply)
    else if (commit) CreditBalanceProtocol.CommitIncomingCredits(txid, id, reply)
    else CreditBalanceProtocol.CancelIncomingCredit(txid, id, reply)

  private def p21Fund(kit: ActorTestKit, ref: akka.actor.typed.RecipientRef[net.imadz.metarch.application.aggregates.CreditBalanceProtocol.CreditBalanceCommandFamily], id: String): Unit = {
    val seed = "p21-seed-" + id
    assert(askNow(kit, ref)(reply => CreditBalanceProtocol.RecordIncomingCredits(seed, id, SeedAmount, reply)).error.isEmpty)
    assert(askNow(kit, ref)(reply => CreditBalanceProtocol.CommitIncomingCredits(seed, id, reply)).error.isEmpty)
  }

  private def p21Amounts: Vector[net.imadz.metarch.domain.values.Money] = Vector(Money("30", Currency), Money("31", Currency),
    Money("30", "YTS"), Money("0", Currency), Money("-1", Currency), Money("not-minor", Currency))

  for (source <- Vector(true, false); commit <- Vector(true, false)) {
    test("P21 participant terminal barrier: real commands and same-journal recovery; source=" + source + "; commit=" + commit) {
      val kit = ActorTestKit("P21Participant" + source + commit, singleNodeConfig())
      try {
        val id = "p21-participant-" + source + "-" + commit; val txid = "tx-" + id
        val first = kit.spawn(aggregateBehavior(id))
        p21Fund(kit, first, id)
        val amount = Money("30", Currency)
        assert(askNow(kit, first)(reply => p21PrepareCommand(source, txid, id, amount, reply)).error.isEmpty)
        assert(askNow(kit, first)(reply => p21TerminalCommand(source, commit, txid, id, reply)).error.isEmpty)
        val before = stateOf(kit, first); val journal = p21AllEvents(kit, id)
        assert(p19Events(kit, id, txid).size == 2 && journal.size == 4)
        assert((if (commit) before.committed else before.compensated)(txid) == amount)
        assert(!(if (commit) before.compensated else before.committed).contains(txid))
        assert(!before.reservedAmount.contains(txid) && !before.incomingCredits.contains(txid))
        val expected = if (source && commit) "99970" else if (!source && commit) "100030" else "100000"
        assert(before.accountBalance(Currency).minorUnits == expected)
        def late(ref: ActorRef[net.imadz.metarch.application.aggregates.CreditBalanceProtocol.CreditBalanceCommandFamily]): Unit = for (changed <- p21Amounts) {
          val reply = askNow(kit, ref)(r => p21PrepareCommand(source, txid, id, changed, r))
          assert(reply.error.map(_.code).contains(if (commit) "60011" else "60012"))
          assert(stateOf(kit, ref) == before)
          assert(p21AllEvents(kit, id) == journal)
        }
        late(first)
        kit.stop(first)
        val again = kit.spawn(aggregateBehavior(id))
        assert(stateOf(kit, again) == before)
        assert(p21AllEvents(kit, id) == journal)
        late(again)
      } finally kit.shutdownTestKit()
    }
  }

  test("P21 real Host terminal barrier: Prepare remains Unknown without reopening facts or receipt") {
    val port = freePort(); val name = "P21HostBarrier"
    val kit = ActorTestKit(name, clusterConfig(port, "\"akka://" + name + "@127.0.0.1:" + port + "\""))
    try {
      val sharding = initSharding(kit); awaitMembers(kit, 1)
      implicit val ec: ExecutionContext = kit.system.executionContext
      val host = new FixtureHost(kit.system, sharding)
      for (source <- Vector(true, false); commit <- Vector(true, false)) {
        val id = "p21-host-" + source + "-" + commit; val txid = "tx-" + id
        val ref = entityRef(sharding, id); p21Fund(kit, ref, id)
        val amount = Money("30", Currency); val identity = p19Identity(host, txid, id, source)
        val prepared = if (source) host.reserve_sourcePrepareBinding.execute(identity, SagaModule.Reserve_sourcePrepareInput(txid, id, amount))
          else host.reserve_targetPrepareBinding.execute(identity, SagaModule.Reserve_targetPrepareInput(txid, id, amount))
        assert(Await.result(prepared, 10.seconds).isInstanceOf[ConfirmedReceipt[_]])
        val request = OperationRequest(identity.copy(phase = if (commit) Phase.Commit else Phase.Compensate), SagaModule.Args(id, id, amount))
        val terminal = p20Port(host, source, commit)
        val confirmed = Await.result(terminal.execute(request), 10.seconds)
        assert(confirmed == ConfirmedReceipt(request.identity, txid))
        val receiptBytes = terminal.receiptCodec.encode(txid)
        val before = stateOf(kit, ref); val journal = p21AllEvents(kit, id)
        for (changed <- p21Amounts) {
          val query = if (source) host.reserve_sourcePrepareBinding.query(identity, SagaModule.Reserve_sourcePrepareInput(txid, id, changed))
            else host.reserve_targetPrepareBinding.query(identity, SagaModule.Reserve_targetPrepareInput(txid, id, changed))
          val execute = if (source) host.reserve_sourcePrepareBinding.execute(identity, SagaModule.Reserve_sourcePrepareInput(txid, id, changed))
            else host.reserve_targetPrepareBinding.execute(identity, SagaModule.Reserve_targetPrepareInput(txid, id, changed))
          for (outcome <- Vector(Await.result(query, 10.seconds), Await.result(execute, 10.seconds)))
            assert(outcome match { case Unknown(_, reason) => reason.startsWith("MONEY_PREPARE_TERMINAL_FACT"); case _ => false })
          assert(stateOf(kit, ref) == before)
          assert(p21AllEvents(kit, id) == journal)
          assert(Await.result(terminal.query(request), 10.seconds) == confirmed)
          assert(terminal.receiptCodec.encode(txid) == receiptBytes)
        }
      }
    } finally kit.shutdownTestKit()
  }

  test("P21 ordered mailbox barrier: terminal-first rejects, live-repeat-first preserves old behavior") {
    val kit = ActorTestKit("P21OrderedBarrier", singleNodeConfig())
    try {
      for (source <- Vector(true, false); commit <- Vector(true, false); terminalFirst <- Vector(true, false)) {
        val id = "p21-order-" + source + "-" + commit + "-" + terminalFirst; val txid = "tx-" + id
        val ref = kit.spawn(aggregateBehavior(id)); p21Fund(kit, ref, id)
        val amount = Money("30", Currency)
        assert(askNow(kit, ref)(r => p21PrepareCommand(source, txid, id, amount, r)).error.isEmpty)
        val replies = kit.createTestProbe[CreditBalanceProtocol.CreditBalanceReply]()
        // Both commands are sent to the same local ActorRef from this test thread;
        // probe expectations acknowledge the actual durable command order, not sleeps.
        if (terminalFirst) {
          ref ! p21TerminalCommand(source, commit, txid, id, replies.ref)
          ref ! p21PrepareCommand(source, txid, id, amount, replies.ref)
          assert(replies.receiveMessage().error.isEmpty)
          assert(replies.receiveMessage().error.map(_.code).contains(if (commit) "60011" else "60012"))
        } else {
          ref ! p21PrepareCommand(source, txid, id, amount, replies.ref)
          ref ! p21TerminalCommand(source, commit, txid, id, replies.ref)
          val repeated = replies.receiveMessage()
          if (source) assert(repeated.error.isEmpty) else assert(repeated.error.map(_.code).contains("60007"))
          assert(replies.receiveMessage().error.isEmpty)
        }
        val state = stateOf(kit, ref)
        assert(p19Events(kit, id, txid).size == 2 && p21AllEvents(kit, id).size == 4)
        assert((if (commit) state.committed else state.compensated)(txid) == amount)
        assert(!state.reservedAmount.contains(txid) && !state.incomingCredits.contains(txid))
        assert(state.accountBalance(Currency).minorUnits == (if (source && commit) "99970" else if (!source && commit) "100030" else "100000"))
      }
    } finally kit.shutdownTestKit()
  }

  test("P21 synthetic rule precedence: terminal markers beat live empty-success and amount checks") {
    val txid = "p21-synthetic"; val amount = Money("30", Currency)
    val base = net.imadz.metarch.domain.entities.CreditBalanceEntity.empty("p21-synthetic-resource").copy(
      accountBalance = Map(Currency -> SeedAmount), reservedAmount = Map(txid -> amount), incomingCredits = Map(txid -> amount))
    def rule(source: Boolean, state: net.imadz.metarch.domain.entities.CreditBalanceEntity.CreditBalanceState, value: net.imadz.metarch.domain.values.Money) =
      if (source) net.imadz.metarch.domain.invariant.CreditBalanceRules.ReserveFundsRule(state, net.imadz.metarch.domain.invariant.params.CreditBalanceRuleParams.ReserveFundsParams(txid, value))
      else net.imadz.metarch.domain.invariant.CreditBalanceRules.RecordIncomingCreditsRule(state, net.imadz.metarch.domain.invariant.params.CreditBalanceRuleParams.RecordIncomingCreditsParams(txid, value))
    val corrupt = null.asInstanceOf[net.imadz.metarch.domain.values.Money]
    val states = Vector(
      base.copy(committed = Map(txid -> amount)) -> "60011",
      base.copy(compensated = Map(txid -> amount)) -> "60012",
      base.copy(committed = Map(txid -> amount), compensated = Map(txid -> amount)) -> "60011",
      base.copy(committed = Map(txid -> corrupt)) -> "60011",
      base.copy(compensated = Map(txid -> Money("", Currency))) -> "60012")
    for (source <- Vector(true, false); (state, expected) <- states; value <- p21Amounts) {
      val result = rule(source, state, value)
      assert(result match { case Left(error) => error.code == expected; case _ => false })
    }
    assert(rule(true, base, amount) == Right(Nil))
    assert(rule(false, base, amount) match { case Left(error) => error.code == "60007"; case _ => false })
  }

  // ---------- C: coordinator recovery ----------

  test("C1 recovery: an interrupted saga resumes to a terminal state") {
    val port = freePort()
    val kit = ActorTestKit("SafetyRecoveryC1", clusterConfig(port, s"\"akka://SafetyRecoveryC1@127.0.0.1:$port\""))
    try {
      val sharding = initSharding(kit)
      awaitMembers(kit, 1)
      seedFunds(kit, From, "seed-c1-from")
      seedFunds(kit, To, "seed-c1-to")
      implicit val system: ActorSystem[_] = kit.system
      implicit val ec: ExecutionContext = kit.system.executionContext
      val coordinator = StrictSagaEntry.spawn(kit.system, sharding, ReconcileToken)
      startSaga(kit, sharding, coordinator, "op-c1", Money("20", Currency))
      Thread.sleep(250) // mid-flight: the pinned interaction timeout is 1000ms
      // Kill through the classic cell (PoisonPill is cell-intercepted regardless of
    // the typed behavior's internal state) and await termination on a death watch.
      coordinator.toClassic ! akka.actor.PoisonPill
      // Re-spawn only succeeds once the old actor (same system-actor name) is dead —
      // the loop itself is the termination gate; the pill is cell-intercepted.
      var again: ActorRef[StrictSagaCoordinator.Command] = null
      val respawnDeadline = System.currentTimeMillis() + 20000L
      while (again == null && System.currentTimeMillis() < respawnDeadline) {
        try again = StrictSagaEntry.spawn(kit.system, sharding, ReconcileToken)
        catch { case _: Throwable => Thread.sleep(200) }
      }
      require(again != null, "the interrupted coordinator did not terminate in time")
      // RecoveryCompleted is inert by runtime design (reconcile-before-resume): the
      // recovered coordinator holds the interrupted transaction until an authorized
      // bounded Reconcile resumes it — the queries re-read the durable evidence.
      implicit val timeout: Timeout = Timeout(10.seconds)
      val recovered = Await.result(StrictSagaEntry.status(again), 10.seconds)
      require(recovered.identity.isDefined, "recovered state carries no identity")
      val reconcileProbe = kit.createTestProbe[StrictSagaCoordinator.Reply]()
      again ! StrictSagaCoordinator.Reconcile(recovered.identity.get, ReconcileToken, 32, reconcileProbe.ref)
      val state = awaitTerminal(kit, again)
      assert(state.terminal || state.status == StrictStatus.RecoveryRequired)
      // Outcome-bounded conservation: succeeded moved exactly the value; aborted restored it;
      // RecoveryRequired awaits authorized reconciliation (manual path, out of spec scope).
      if (state.status == StrictStatus.Succeeded) {
        assert(balance(kit, entityRef(sharding, From)) == BigInt("99980"))
        assert(balance(kit, entityRef(sharding, To)) == BigInt("100020"))
      } else if (state.status == StrictStatus.Aborted) {
        assert(balance(kit, entityRef(sharding, From)) == BigInt("100000"))
        assert(balance(kit, entityRef(sharding, To)) == BigInt("100000"))
      } else assert(state.status == StrictStatus.RecoveryRequired)
    } finally kit.shutdownTestKit()
  }

  // ---------- D: the deployment face (shared MongoDB journal) ----------

  test("D1 shared durable journal: two clustered systems complete a transfer over one Mongo journal") {
    assume(mongoReachable(), s"MongoDB not reachable at $MongoHostPort — the deployment face (D1-D4) requires the shared durable journal")
    val uri = mongoUri(s"strict_deployment_d1_${System.nanoTime()}")
    val portA = freePort()
    val kitA = ActorTestKit("SafetyClusterD1", mongoClusterConfig(portA, s"\"akka://SafetyClusterD1@127.0.0.1:$portA\"", uri))
    val kitB = ActorTestKit("SafetyClusterD1", mongoClusterConfig(freePort(), s"\"akka://SafetyClusterD1@127.0.0.1:$portA\"", uri))
    try {
      val shardingA = initSharding(kitA)
      val shardingB = initSharding(kitB)
      awaitMembers(kitA, 2)
      awaitMembers(kitB, 2)
      // One shared journal: fund once through the aggregate's own command face — every
      // node reads the same durable state (the per-system test-kit journals are gone).
      seedFundsByCommands(kitA, shardingA, From, "seed-d1-from")
      seedFundsByCommands(kitA, shardingA, To, "seed-d1-to")
      implicit val ec: ExecutionContext = kitB.system.executionContext
      // ClusterSingleton runs the coordinator on the cluster's OLDEST member — every
      // node must init the singleton; the returned proxies route cluster-wide.
      val coordinatorA = StrictSagaEntry.spawnClusterSingleton(kitA.system, shardingA, ReconcileToken)
      val coordinatorB = StrictSagaEntry.spawnClusterSingleton(kitB.system, shardingB, ReconcileToken)
      startSaga(kitB, shardingB, coordinatorB, "op-d1", Money("100", Currency))
      val state = awaitTerminal(kitB, coordinatorB)
      assert(state.status == StrictStatus.Succeeded)
      // Values verified through BOTH systems' sharding proxies — cross-node asks
      // against one shared durable journal.
      assert(balance(kitA, entityRef(shardingA, From)) == BigInt("99900"))
      assert(balance(kitB, entityRef(shardingB, To)) == BigInt("100100"))
      assertPublished(kitA, shardingA, state, "succeeded")
    } finally { kitB.shutdownTestKit(); kitA.shutdownTestKit() }
  }

  test("D2 event-stream source: the persisted trigger event starts the saga with no direct coordinator call") {
    assume(mongoReachable(), s"MongoDB not reachable at $MongoHostPort — the deployment face (D1-D4) requires the shared durable journal")
    val port = freePort()
    val kit = ActorTestKit("SafetyEventSourceD2", mongoClusterConfig(port, s"\"akka://SafetyEventSourceD2@127.0.0.1:$port\"", mongoUri(s"strict_deployment_d2_${System.nanoTime()}")))
    try {
      val sharding = initSharding(kit)
      awaitMembers(kit, 1)
      seedFundsByCommands(kit, sharding, From, "seed-d2-from")
      seedFundsByCommands(kit, sharding, To, "seed-d2-to")
      implicit val ec: ExecutionContext = kit.system.executionContext
      val coordinator = StrictSagaEntry.spawnClusterSingleton(kit.system, sharding, ReconcileToken)
      // Install the journal event-stream source BEFORE the command: whatever the
      // stream's catch-up semantics, the trigger event persists after the install.
      StrictSagaEntry.installEventSource(kit.system, sharding, coordinator)
      // Send the command to the AGGREGATE (never the coordinator): the persisted
      // trigger event is what starts the saga.
      val opId = "op-d2-" + System.currentTimeMillis()
      val commandReply = askNow(kit, entityRef(sharding, From))(replyTo =>
        CreditBalanceProtocol.StartTransfer(opId, From, To, Money("100", Currency), replyTo))
      assert(commandReply.error.isEmpty)
      val state = awaitTerminal(kit, coordinator)
      assert(state.status == StrictStatus.Succeeded)
      assert(state.identity.get.transactionId == opId)
      assert(balance(kit, entityRef(sharding, From)) == BigInt("99900"))
      assert(balance(kit, entityRef(sharding, To)) == BigInt("100100"))
      // No manual publish here: the event-stream source owns the completion side.
      awaitPublished(kit, sharding, opId, "succeeded")
    } finally kit.shutdownTestKit()
  }

  test("D3 physical two-JVM deployment: an event-driven saga across two processes and one journal") {
    assume(mongoReachable(), s"MongoDB not reachable at $MongoHostPort — the deployment face (D1-D4) requires the shared durable journal")
    val classpath = System.getProperty("java.class.path")
    assume(classpath.split(java.io.File.pathSeparator).exists(p => p.contains("target") && p.contains("scala-2.13")),
      "D3 requires Test/fork — java.class.path must carry the application test classpath")
    val uri = mongoUri(s"strict_deployment_d3_${System.nanoTime()}")
    val portSeed = freePort()
    val seedAddr = s"\"akka://SafetyClusterD3@127.0.0.1:$portSeed\""
    val evidenceDir = new java.io.File("target/deployment-face")
    evidenceDir.mkdirs()
    val javaBin = s"${System.getProperty("java.home")}/bin/java"
    def node(args: Seq[String], log: String): java.lang.Process =
      new java.lang.ProcessBuilder((Vector(javaBin, "-cp", classpath, "fixture.FixtureDeploymentNode") ++ args): _*)
        .redirectOutput(new java.io.File(evidenceDir, log))
        .redirectErrorStream(true)
        .start()
    val opId = "op-d3-" + System.currentTimeMillis()
    val seed = node(Vector("seed", portSeed.toString, seedAddr, uri), "d3-seed.log")
    try {
      // Head start: wait until the seed node's artery port accepts connections.
      val seedUp = System.currentTimeMillis() + 30000L
      var bound = false
      while (!bound && System.currentTimeMillis() < seedUp) {
        try { val s = new java.net.Socket("127.0.0.1", portSeed); s.close(); bound = true }
        catch { case _: Throwable => Thread.sleep(200) }
      }
      assert(bound, "seed node did not bind its artery port in 30s — see target/deployment-face/d3-seed.log")
      val join = node(Vector("join", freePort().toString, seedAddr, uri, opId, From, To, "100"), "d3-join.log")
      try {
        val joinDone = join.waitFor(180, java.util.concurrent.TimeUnit.SECONDS)
        assert(joinDone, "join node did not finish in 180s — see target/deployment-face/d3-join.log and d3-seed.log")
        assert(join.exitValue() == 0, s"join node failed (exit ${join.exitValue()}) — see target/deployment-face/d3-join.log and d3-seed.log")
        val source = scala.io.Source.fromFile(new java.io.File(evidenceDir, "d3-join.log"))
        val out = try source.mkString finally source.close()
        assert(out.contains(s"D3-RESULT status=Succeeded op=$opId"), s"join node did not report a succeeded transfer — output: $out")
                assert(out.contains("alice=99900") && out.contains("bob=100100"), s"balances wrong — output: $out")
      } finally if (join.isAlive) join.destroy()
    } finally {
      if (seed.isAlive) { seed.destroy(); seed.waitFor(10, java.util.concurrent.TimeUnit.SECONDS) }
    }
  }

  test("D4 physical two-JVM failover: coordinator-node loss converges through singleton migration and an authorized reconcile") {
    assume(mongoReachable(), s"MongoDB not reachable at $MongoHostPort — the deployment face (D1-D4) requires the shared durable journal")
    val classpath = System.getProperty("java.class.path")
    assume(classpath.split(java.io.File.pathSeparator).exists(p => p.contains("target") && p.contains("scala-2.13")),
      "D4 requires Test/fork — java.class.path must carry the application test classpath")
    val uri = mongoUri(s"strict_deployment_d4_${System.nanoTime()}")
    val portSeed = freePort()
    val seedAddr = s"\"akka://SafetyClusterD4@127.0.0.1:$portSeed\""
    val evidenceDir = new java.io.File("target/deployment-face")
    evidenceDir.mkdirs()
    val javaBin = s"${System.getProperty("java.home")}/bin/java"
    def node(args: Seq[String], log: String): java.lang.Process =
      new java.lang.ProcessBuilder((Vector(javaBin, "-cp", classpath, "fixture.FixtureDeploymentNode") ++ args): _*)
        .redirectOutput(new java.io.File(evidenceDir, log))
        .redirectErrorStream(true)
        .start()
    def tailOf(log: java.io.File): String = {
      val s = scala.io.Source.fromFile(log)
      try s.mkString finally s.close()
    }
    val opId = "op-d4-" + System.currentTimeMillis()
    val seed = node(Vector("seed", portSeed.toString, seedAddr, uri), "d4-seed.log")
    try {
      // Head start: wait until the seed node's artery port accepts connections.
      val seedUp = System.currentTimeMillis() + 30000L
      var bound = false
      while (!bound && System.currentTimeMillis() < seedUp) {
        try { val s = new java.net.Socket("127.0.0.1", portSeed); s.close(); bound = true }
        catch { case _: Throwable => Thread.sleep(200) }
      }
      assert(bound, "seed node did not bind its artery port in 30s — see target/deployment-face/d4-seed.log")
      val joinLog = new java.io.File(evidenceDir, "d4-join.log")
      val join = node(Vector("failover", freePort().toString, seedAddr, uri, opId, From, To, "100"), "d4-join.log")
      try {
        // Destroy the coordinator node as early as the transaction is observable
        // (identity defined). Whatever instant the loss lands — before the Start,
        // mid-flight or after the terminal marker — the deployment converges: the
        // recovered journal state resumes on the migrated singleton and the authorized
        // reconcile completes the saga (the deterministic mid-flight kill semantics
        // are C1's domain; here the physical topology is the subject).
        val started = System.currentTimeMillis() + 60000L
        var seen = false
        while (!seen && System.currentTimeMillis() < started) {
          if (joinLog.exists() && tailOf(joinLog).contains("D4-STARTED")) seen = true
          else Thread.sleep(25)
        }
        assert(seen, "failover node never reported D4-STARTED in 60s — see target/deployment-face/d4-join.log")
        seed.destroy() // SIGTERM → CoordinatedShutdown → graceful cluster leave → singleton migrates
        seed.waitFor(30, java.util.concurrent.TimeUnit.SECONDS)
        val joinDone = join.waitFor(180, java.util.concurrent.TimeUnit.SECONDS)
        assert(joinDone, "failover node did not finish in 180s — see target/deployment-face/d4-join.log and d4-seed.log")
        assert(join.exitValue() == 0, s"failover node failed (exit ${join.exitValue()}) — see target/deployment-face/d4-join.log and d4-seed.log")
        val out = tailOf(joinLog)
        assert(out.contains(s"D4-RESULT status=Succeeded op=$opId"), s"failover node did not report a succeeded transfer — output: $out")
                assert(out.contains("alice=99900") && out.contains("bob=100100"), s"balances wrong — output: $out")
        assert(out.contains("ledger=succeeded"), s"the source did not publish the ledger after the node loss — output: $out")
      } finally if (join.isAlive) join.destroy()
    } finally {
      if (seed.isAlive) { seed.destroy(); seed.waitFor(10, java.util.concurrent.TimeUnit.SECONDS) }
    }
  }

  private def freePort(): Int = {
    val socket = new java.net.ServerSocket(0)
    try socket.getLocalPort finally socket.close()
  }

  test("production conf chain assembles the shared durable journal (saga-gated conf face)") {
    // The emitted conf/persistence.conf rides the application.conf include chain as the
    // PRODUCTION default; every other test config overrides the journal explicitly, so
    // this asserts the assembly (parse only — no journal instantiation).
    val config = ConfigFactory.load()
    assert(config.getString("akka.persistence.journal.plugin") == "akka-contrib-mongodb-persistence-journal")
    assert(config.getString("akka.persistence.snapshot-store.plugin") == "akka-contrib-mongodb-persistence-snapshot")
    assert(config.getString("akka.contrib.persistence.mongodb.mongo.driver") == "akka.contrib.persistence.mongodb.RxMongoPersistenceExtension")
    assert(config.hasPath("akka.contrib.persistence.mongodb.mongo.mongouri"))
  }
}
